{
    public class PublicIpVariable : IVariableProvider
    {
        private static readonly HttpClient httpClient = new HttpClient();
        private static DateTime lastRefreshTime = DateTime.MinValue;
        private static string cachedPublicIp = string.Empty;

        public Dictionary<string, Func<string>> GetVariables()
        {
            return new Dictionary<string, Func<string>>()
            {
                { "publicIp", GetPublicIp }
            };
        }

        private string GetPublicIp()
        {
            if ((DateTime.Now - lastRefreshTime).TotalMinutes < 1)
            {
                return cachedPublicIp;
            }

            _ = Task.Run(async () =>
            {
                try
                {
                    cachedPublicIp = await httpClient.GetStringAsync("http://icanhazip.com");
                    lastRefreshTime = DateTime.Now;
                }
                catch (Exception ex)
                {
                    // Log the exception or handle it as needed
                    Console.WriteLine($"Failed to refresh public IP: {ex.Message}");
                }
            });

            return cachedPublicIp.Trim();
        }
    }
}

